// Backward-compat: full text per policy for legacy search
export interface Policy { id: string; name: string; fileUrl: string; sourceDocumentName: string; description: string; content: string; }
export const ARVIND_POLICIES: Policy[] = POLICY_META.map(m => ({
  ...m,
  content: ALL_CHUNKS.filter(c => c.policyId === m.id).map(c => c.text).join('\n\n'),
}));


// ─── BM25 Search ──────────────────────────────────────────────────────────────
const STOP_WORDS = new Set([
  "the","is","in","it","of","and","a","an","to","was","for","on","are",
  "as","at","be","this","that","with","from","by","or","but","not","have",
  "employees","employee","company","arvind","policy","shall","must","per",
]);

function tokenize(text: string): string[] {
  return text.toLowerCase()
    .match(/[a-z0-9]+(?:-[a-z0-9]+)*/g)
    ?.filter(t => !STOP_WORDS.has(t) && t.length > 1) ?? [];
}

const AVG_DL = ALL_CHUNKS.reduce((s, c) => s + c.tokens.length, 0) / ALL_CHUNKS.length;
const K1 = 1.5, B = 0.75;

export function bm25Search(query: string, topK = 8): Chunk[] {
  const qTokens = tokenize(query);
  if (!qTokens.length) return [];

  const scores = new Float32Array(ALL_CHUNKS.length);

  for (const qt of qTokens) {
    const idfVal = IDF[qt] ?? 0;
    if (idfVal === 0) continue;
    for (let i = 0; i < ALL_CHUNKS.length; i++) {
      const chunk = ALL_CHUNKS[i];
      const dl = chunk.tokens.length;
      const tf = chunk.tokens.filter(t => t === qt).length;
      if (tf === 0) continue;
      const norm = K1 * ((1 - B) + B * (dl / AVG_DL));
      scores[i] += idfVal * ((tf * (K1 + 1)) / (tf + norm));
    }
  }

  // Grade boost: M1, BM-H3, E2, H6, etc.
  const gradeMatch = query.match(/\b(bmh?\d*|bm-?h\d+|m[1-9]|h[\d]+|e[1-2]|ot|get|mt|m3h1)\b/i);
  if (gradeMatch) {
    const grade = gradeMatch[0].toLowerCase().replace(/-/g, "");
    for (let i = 0; i < ALL_CHUNKS.length; i++) {
      const t = ALL_CHUNKS[i].text.toLowerCase().replace(/-/g, "");
      if (t.includes(grade)) scores[i] += 8;
    }
  }

  // Table boost for numeric queries
  const wantsTable = /limit|lodging|boarding|rate|amount|allowance|entitlement|cab|conveyance|reimburs/i.test(query);
  if (wantsTable) {
    for (let i = 0; i < ALL_CHUNKS.length; i++) {
      if (ALL_CHUNKS[i].text.includes("[TABLE]") || ALL_CHUNKS[i].text.includes("[TABLE FACTS]")) {
        scores[i] += 5;
      }
    }
  }

  // Collect top-K
  const indexed = Array.from(scores.entries())
    .filter(([, s]) => s > 0)
    .sort(([, a], [, b]) => b - a)
    .slice(0, topK);

  return indexed.map(([i]) => ALL_CHUNKS[i]);
}

export function formatTableChunkText(text: string): string {
  if (text.includes("|") && text.includes("---")) {
    return text; // Already a Markdown table
  }

  const lines = text.split("\n").map(l => l.trim()).filter(Boolean);
  if (lines.length < 2) return text;

  const tableData = lines.map(line => {
    return line.split(/\s{2,}|\t|\|/).map(c => c.trim()).filter(Boolean);
  });

  const colCounts = tableData.map(row => row.length);
  const maxCols = Math.max(...colCounts);
  if (maxCols <= 1) return text;

  const markdownRows: string[] = [];
  const header = tableData[0];
  while (header.length < maxCols) header.push("");
  markdownRows.push(`| ${header.join(" | ")} |`);

  const separator = Array(maxCols).fill("---");
  markdownRows.push(`| ${separator.join(" | ")} |`);

  for (let i = 1; i < tableData.length; i++) {
    const row = tableData[i];
    while (row.length < maxCols) row.push("");
    markdownRows.push(`| ${row.join(" | ")} |`);
  }

  return markdownRows.join("\n");
}

// Context builder: max 14000 chars, deduped by chunk id with parent-child page expansion
export function buildContext(chunks: Chunk[], maxChars = 14000): string {
  const seen = new Set<number>();
  const parts: string[] = [];
  let total = 0;
  for (const c of chunks) {
    if (seen.has(c.id)) continue;
    seen.add(c.id);

    // Dynamic Parent-Child expansion:
    // We fetch all chunks from the same policy and page to reconstruct the complete page parent context.
    const siblingChunks = ALL_CHUNKS.filter(
      sibling => sibling.policyId === c.policyId && sibling.pageNum === c.pageNum
    );
    
    // Sort by id to preserve natural reading order
    siblingChunks.sort((a, b) => a.id - b.id);
    
    // Mark siblings as seen to avoid redundant duplicate sibling page context generations
    siblingChunks.forEach(sibling => seen.add(sibling.id));
    
    // Reconstruct the full parent page context
    const fullText = siblingChunks.map(sibling => {
      return (sibling.text.includes("table belongs") || sibling.text.includes("|"))
        ? formatTableChunkText(sibling.text)
        : sibling.text;
    }).join("\n\n");

    if (total + fullText.length > maxChars) {
      // If expanding is too large, fallback to just this chunk to avoid overflow
      const singleText = (c.text.includes("table belongs") || c.text.includes("|"))
        ? formatTableChunkText(c.text)
        : c.text;
      if (total + singleText.length <= maxChars) {
        parts.push(`[SOURCE: ${c.policyName} | Page ${c.pageNum}]\n${singleText}`);
        total += singleText.length;
      }
      continue;
    }
    
    parts.push(`[SOURCE: ${c.policyName} | Page ${c.pageNum}]\n${fullText}`);
    total += fullText.length;
  }
  return parts.join("\n\n---\n\n");
}
